diff --git a/src/hybrid/program_buffer.hpp b/src/hybrid/program_buffer.hpp
index d26e382..4af7afd 100644
--- a/src/hybrid/program_buffer.hpp
+++ b/src/hybrid/program_buffer.hpp
@@ -89,6 +89,18 @@ inline constexpr uint32_t encode_vse8_v(uint8_t vs3, uint8_t rs1)
          | 0x27u;  // STORE-FP opcode
 }

+// Encode `addi rd, rs1, imm12` (OP-IMM opcode 0x13, funct3=000). The batched
+// V-data sweep advances the scratch base pointer x7 by one register-span
+// between transfers WITHIN a Program-Buffer execution, so the per-register
+// abstract x7 write disappears. imm12 is a signed 12-bit field (-2048..2047).
+inline constexpr uint32_t encode_addi(uint8_t rd, uint8_t rs1, int32_t imm12)
+{
+    return ((uint32_t(imm12) & 0xFFFu) << 20)
+         | ((uint32_t(rs1) & 0x1Fu) << 15)
+         | ((uint32_t(rd)  & 0x1Fu) << 7)
+         | 0x13u;  // OP-IMM opcode (funct3=000)
+}
+
 // Write insns[0..n-1] to progbuf0..n-1 and kEbreak to progbuf[n].
 // Clears any sticky abstractcs.cmderr (W1C), issues kExecProgbufCmd, polls
 // until abstractcs.busy clears, then verifies cmderr stayed clear.
@@ -159,13 +171,34 @@ inline void pb_v_data_sweep(Bus& bus, uint64_t scratch_gpa, uint64_t stride,
     write_register_abstract(bus, regno_gpr(6), kVtypeE8M1);  // e8, m1, ta, ma
     const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
     exec_progbuf(bus, std::span<const uint32_t>{pb_vsetvl});
+
+    // vle8.v/vse8.v are register-indirect with no immediate offset, so the base
+    // pointer x7 must step one register-span between transfers. Advance it with
+    // an `addi` INSIDE the Program Buffer and pack as many (transfer; addi)
+    // pairs as fit (kProgbufMaxInsns / 2 = 7) into each execution. Each PB
+    // execution is one halted-hart DM round-trip (~1000 sim cycles spent in the
+    // busy-poll), so the cost is the NUMBER of executions: batching cuts 32
+    // registers from 32 executions + 32 per-register x7 writes down to
+    // ceil(32/7) = 5 executions and ONE x7 write. x7 persists across executions
+    // (the hart stays halted), so each batch resumes advancing where the last
+    // one stopped.
+    if (stride > 2047)  // addi imm12 is signed 12-bit; the wire span is 128
+        throw std::runtime_error(
+            "pb_v_data_sweep: register stride exceeds the addi imm12 range");
+    write_register_abstract(bus, regno_gpr(7), scratch_gpa);  // base, set once
+
+    constexpr std::size_t kRegsPerBatch = kProgbufMaxInsns / 2;  // 7
+    const uint32_t addi_step = encode_addi(7, 7, static_cast<int32_t>(stride));
+    std::array<uint32_t, kRegsPerBatch * 2> batch{};
+    std::size_t n = 0;
     for (uint16_t i = 0; i < 32; ++i) {
-        write_register_abstract(
-            bus, regno_gpr(7), scratch_gpa + static_cast<uint64_t>(i) * stride);
-        const std::array<uint32_t, 1> pb = {
-            load ? encode_vle8_v(static_cast<uint8_t>(i), 7)
-                 : encode_vse8_v(static_cast<uint8_t>(i), 7) };
-        exec_progbuf(bus, std::span<const uint32_t>{pb});
+        batch[n++] = load ? encode_vle8_v(static_cast<uint8_t>(i), 7)
+                          : encode_vse8_v(static_cast<uint8_t>(i), 7);
+        batch[n++] = addi_step;
+        if (n == batch.size() || i == 31) {
+            exec_progbuf(bus, std::span<const uint32_t>{batch.data(), n});
+            n = 0;
+        }
     }
 }

diff --git a/tests/hybrid/program_buffer.test.cpp b/tests/hybrid/program_buffer.test.cpp
index aea8ca5..8019394 100644
--- a/tests/hybrid/program_buffer.test.cpp
+++ b/tests/hybrid/program_buffer.test.cpp
@@ -113,6 +113,16 @@ TEST_CASE("encode_vse8_v: known encodings (golden hex from riscv64-elf-as)")
     CHECK(encode_vse8_v(31, 7) == 0x02038FA7u);   // vse8.v v31,(x7)
 }

+TEST_CASE("encode_addi: known encodings (golden hex from riscv64-elf-as)")
+{
+    // addi rd, rs1, imm12: OP-IMM (0x13), funct3=000. The V-data sweep advances
+    // the scratch base pointer x7 by one register-span between batched
+    // transfers. Verified with `riscv64-elf-as -march=rv64gcv`.
+    CHECK(encode_addi(7, 7, 128)  == 0x08038393u);  // addi x7,x7,128
+    CHECK(encode_addi(7, 7, 64)   == 0x04038393u);  // addi x7,x7,64
+    CHECK(encode_addi(5, 5, 2047) == 0x7FF28293u);  // addi x5,x5,2047 (max imm)
+}
+
 // ---- exec_progbuf behavioral tests -----------------------------------------

 TEST_CASE("exec_progbuf: single instruction - writes insn, ebreak, exec command")
@@ -205,3 +215,93 @@ TEST_CASE("exec_progbuf: polls while busy before returning")
     const std::array<uint32_t, 1> insns{0x1u};
     CHECK_NOTHROW(exec_progbuf(bus, insns));
 }
+
+// ---- pb_v_data_sweep batching tests ----------------------------------------
+// Each Program-Buffer execution is one halted-hart DM round-trip (~1000 sim
+// cycles in the busy-poll), so the cost is the NUMBER of executions, not the
+// bytes moved. The sweep batches (transfer; addi) pairs into each execution
+// and advances the base pointer x7 with the in-buffer addi, so 32 registers
+// cost ceil(32/7)=5 executions and ONE x7 abstract write -- instead of 32
+// executions plus 32 per-register x7 writes.
+
+namespace {
+constexpr uint8_t kCommandReg = 0x17u;
+
+int count_exec_cmds(const RecBus& bus)
+{
+    int n = 0;
+    for (const auto& w : bus.writes)
+        if (w.reg == kCommandReg && w.val == kExecProgbufCmd) ++n;
+    return n;
+}
+
+int count_x7_abstract_writes(const RecBus& bus)
+{
+    int n = 0;
+    for (const auto& w : bus.writes)
+        if (w.reg == kCommandReg && (w.val & 0xFFFFu) == regno_gpr(7)
+            && ((w.val >> 16) & 1u) != 0u)
+            ++n;
+    return n;
+}
+
+bool progbuf_holds(const RecBus& bus, uint32_t insn)
+{
+    for (const auto& w : bus.writes)
+        if (w.reg >= kProgbuf0 && w.reg <= kProgbuf0 + kProgbufMaxInsns
+            && w.val == insn)
+            return true;
+    return false;
+}
+}  // namespace
+
+TEST_CASE("pb_v_data_sweep: batches transfers into few PB executions, "
+          "staging the scratch base pointer once")
+{
+    RecBus bus;
+    constexpr uint64_t kScratch = 0x90000000ull;
+    constexpr uint64_t kStride  = 128;  // HYBRID_VLEN_BYTES_MAX wire span
+
+    pb_v_data_sweep(bus, kScratch, kStride, /*vlenb=*/64, /*load=*/true);
+
+    // 1 vsetvl execution + ceil(32/7)=5 batch executions = 6 (was 1 + 32 = 33).
+    CHECK(count_exec_cmds(bus) == 6);
+    // The base pointer is staged once; the in-buffer addi advances it.
+    CHECK(count_x7_abstract_writes(bus) == 1);
+    CHECK(progbuf_holds(bus, encode_addi(7, 7, int32_t(kStride))));
+
+    // The single x7 abstract write stages the scratch BASE (data0/data1 are the
+    // two writes immediately preceding the command).
+    bool first_x7_is_base = false;
+    for (std::size_t i = 2; i < bus.writes.size(); ++i) {
+        const auto& w = bus.writes[i];
+        if (w.reg == kCommandReg && (w.val & 0xFFFFu) == regno_gpr(7)
+            && ((w.val >> 16) & 1u) != 0u) {
+            first_x7_is_base =
+                bus.writes[i - 2].reg == kDmiData0
+                && bus.writes[i - 2].val == uint32_t(kScratch & 0xFFFFFFFFu)
+                && bus.writes[i - 1].reg == kDmiData1
+                && bus.writes[i - 1].val == uint32_t(kScratch >> 32);
+            break;
+        }
+    }
+    CHECK(first_x7_is_base);
+
+    // All 32 vle8.v are present across the progbuf slots (not just progbuf0).
+    int found = 0;
+    for (uint16_t v = 0; v < 32; ++v)
+        if (progbuf_holds(bus, encode_vle8_v(uint8_t(v), 7))) ++found;
+    CHECK(found == 32);
+}
+
+TEST_CASE("pb_v_data_sweep: load=false emits a vse8.v for every register")
+{
+    RecBus bus;
+    pb_v_data_sweep(bus, 0x90000000ull, 128, /*vlenb=*/64, /*load=*/false);
+
+    int found = 0;
+    for (uint16_t v = 0; v < 32; ++v)
+        if (progbuf_holds(bus, encode_vse8_v(uint8_t(v), 7))) ++found;
+    CHECK(found == 32);
+    CHECK(count_exec_cmds(bus) == 6);
+}
